 day,start=row['day'],row['start'];z=np.load(O/f'{day}-{start}-effective-bank.npz');a.plot(z['t'],np.rad2deg(z['truth']),color='#173348',lw=2.5,label='Flight');a.plot(z['t'],np.rad2deg(z['model']),color='#178389',lw=2,label='Effective bank model');a.set_title(('Hood River' if day.endswith('03') else 'Trout Lake')+f' · {start} s\nRMS error {row["bank_rmse_deg"]:.1f}°');a.set_xlabel('Prediction time (s)');a.grid(alpha=.2);a.spines[['top','right']].set_visible(False)
